    public static void Binary(ushort index, ref DispatchSink s)
    {
        var lo = 0;
        var hi = s_indices.Length;

        while (lo < hi)
        {
            var mid = (lo + hi) >>> 1;
            if (s_indices[mid] <= index)
                lo = mid + 1;
            else
                hi = mid;
        }

        s.Visit(lo - 1);
    }

